/* ---------------- codepoint buffer ---------------- */
typedef struct { uint32_t *p; size_t n, cap; int oom; } dyn_cp_t;

static void dyn_cp_init(dyn_cp_t *b) { b->p = NULL; b->n = 0; b->cap = 0; b->oom = 0; }
static void dyn_cp_free(dyn_cp_t *b) { free(b->p); b->p = NULL; b->n = b->cap = 0; }

static void *dyn_dbuf_realloc(void *opaque, void *ptr, size_t size)
{
    (void)opaque;
    return realloc(ptr, size);
}

static int dyn_cp_put(dyn_cp_t *b, uint32_t c)
{
    if (b->oom)
        return -1;
    if (b->n == b->cap) {
        size_t nc = b->cap ? b->cap * 2 : 64;
        uint32_t *np = (uint32_t *)realloc(b->p, nc * sizeof(uint32_t));
        if (!np) { b->oom = 1; return -1; }
        b->p = np; b->cap = nc;
    }
    b->p[b->n++] = c;
    return 0;
}

/* ---------------- UTS #46 status lookup ---------------- */
enum {
    IDNA_ST_VALID = 0,      /* default when nothing matches */
    IDNA_ST_IGNORED,
    IDNA_ST_DEVIATION,
    IDNA_ST_MAPPED,
    IDNA_ST_DISALLOWED,
};

/* binary search over [3]-column tables; returns row index or -1 */
static int dyn_tab3(const uint32_t (*tab)[3], int n, uint32_t cp)
{
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (cp < tab[mid][0])      hi = mid - 1;
        else if (cp > tab[mid][1]) lo = mid + 1;
        else                       return mid;
    }
    return -1;
}

static int dyn_tab2(const uint32_t (*tab)[2], int n, uint32_t cp)
{
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (cp < tab[mid][0])      hi = mid - 1;
        else if (cp > tab[mid][1]) lo = mid + 1;
        else                       return mid;
    }
    return -1;
}

/* UTS #46 status of a code point, as the IDNA_ST_* enum */
static int dyn_idna_status(uint32_t cp)
{
    int lo, hi, mid;
    if (cp < 0x80) {
        if (cp >= 'A' && cp <= 'Z')
            return IDNA_ST_MAPPED;
        return IDNA_ST_VALID;
    }
    /* mapped, single-cp target (delta runs) */
    lo = 0; hi = (int)(countof(idna_map_delta)) - 1;
    while (lo <= hi) {
        mid = (lo + hi) / 2;
        if (cp < idna_map_delta[mid][0])      hi = mid - 1;
        else if (cp > idna_map_delta[mid][1]) lo = mid + 1;
        else                                  return IDNA_ST_MAPPED;
    }
    /* mapped, multi-cp target */
    lo = 0; hi = (int)(countof(idna_map_multi)) - 1;
    while (lo <= hi) {
        mid = (lo + hi) / 2;
        if (cp < idna_map_multi[mid][0])      hi = mid - 1;
        else if (cp > idna_map_multi[mid][0]) lo = mid + 1;
        else                                  return IDNA_ST_MAPPED;
    }
    {
        int i = dyn_tab3(idna_status_ranges, countof(idna_status_ranges), cp);
        if (i >= 0)
            return idna_status_ranges[i][2];   /* 1=ignored 2=deviation 3=disallowed */
    }
    return IDNA_ST_VALID;
}

/* Map one code point under UTS #46 processing. Appends result to `out`.
   Returns 0 on success, -1 on OOM. */
static int dyn_idna_map_cp(uint32_t cp, int transitional, int drop_disallowed,
                           dyn_cp_t *out)
{
    int i, st;
    uint32_t v, t0, t1;
    if (cp < 0x80) {
        if (cp >= 'A' && cp <= 'Z')
            return dyn_cp_put(out, cp + 0x20);
        return dyn_cp_put(out, cp);
    }
    /* U+1E9E capital sharp s: mapped to 0x00DF in the table; under
       transitional processing it is mapped to "ss" (UTS #46 section 5) */
    if (cp == 0x1E9E)
        return transitional ? (dyn_cp_put(out, 's') | dyn_cp_put(out, 's'))
                            : dyn_cp_put(out, 0x00DF);
    /* mapped single-cp delta */
    {
        int lo = 0, hi = (int)(countof(idna_map_delta)) - 1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (cp < idna_map_delta[mid][0])      hi = mid - 1;
            else if (cp > idna_map_delta[mid][1]) lo = mid + 1;
            else {
                int32_t d = (int32_t)idna_map_delta[mid][2];
                return dyn_cp_put(out, cp + d);
            }
        }
    }
    /* mapped multi-cp */
    {
        int lo = 0, hi = (int)(countof(idna_map_multi)) - 1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (cp < idna_map_multi[mid][0])      hi = mid - 1;
            else if (cp > idna_map_multi[mid][0]) lo = mid + 1;
            else {
                uint32_t off = idna_map_multi[mid][1], len = idna_map_multi[mid][2];
                for (i = 0; i < (int)len; i++) {
                    if (dyn_cp_put(out, idna_map_multi_pool[off + i]))
                        return -1;
                }
                return 0;
            }
        }
    }
    st = IDNA_ST_VALID;
    {
        int ri = dyn_tab3(idna_status_ranges, countof(idna_status_ranges), cp);
        if (ri >= 0)
            st = idna_status_ranges[ri][2];
    }
    switch (st) {
    case IDNA_ST_IGNORED:
        return 0;                       /* removed */
    case IDNA_ST_DEVIATION:
        if (!transitional)
            return dyn_cp_put(out, cp);
        /* transitional: apply the deviation mapping */
        if (cp == 0x00DF) { /* sharp s -> ss */
            if (dyn_cp_put(out, 's')) return -1;
            return dyn_cp_put(out, 's');
        }
        if (cp == 0x03C2)               /* final sigma -> sigma */
            return dyn_cp_put(out, 0x03C3);
        if (cp == 0x200C || cp == 0x200D) /* joiners -> removed */
            return 0;
        return dyn_cp_put(out, cp);
    case IDNA_ST_DISALLOWED:
        /* ToASCII DELETES disallowed characters (UTS #46 section 4.2
           mapping); ToUnicode keeps them so validation can report V7. */
        return drop_disallowed ? 0 : dyn_cp_put(out, cp);
    default:
        v = cp; t0 = t1 = 0; (void)v; (void)t0; (void)t1;
        return dyn_cp_put(out, cp);     /* valid */
    }
}


/* ---------------- punycode (RFC 3492) ---------------- */
enum { PC_BASE = 36, PC_TMIN = 1, PC_TMAX = 26, PC_SKEW = 38, PC_DAMP = 700,
       PC_INITIAL_N = 128, PC_INITIAL_BIAS = 72, PC_DELIM = 0x2D };

static int pc_adapt(int delta, int numpoints, int firsttime)
{
    int k = 0;
    delta = firsttime ? delta / PC_DAMP : delta / 2;
    delta += delta / numpoints;
    while (delta > ((PC_BASE - PC_TMIN) * PC_TMAX) / 2) {
        delta /= PC_BASE - PC_TMIN;
        k += PC_BASE;
    }
    return k + (PC_BASE - PC_TMIN + 1) * delta / (delta + PC_SKEW);
}

static int pc_digit(int c)
{
    if (c >= 'a' && c <= 'z') return c - 'a';
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= '0' && c <= '9') return c - '0' + 26;
    return -1;
}

/* Encode `cps` into `out` (bytes). Returns 0 or -1 on error (a code point
   that punycode cannot represent: > 0x10FFFF or a surrogate). */
static int pc_encode(const uint32_t *cps, int n, dyn_cp_t *out)
{
    int i, h, b, bias, nout;
    int64_t delta;
    uint32_t nval, m;
    for (i = 0; i < n; i++) {
        if (cps[i] > 0x10FFFF || (cps[i] >= 0xD800 && cps[i] <= 0xDFFF))
            return -1;
    }
    h = b = 0;
    for (i = 0; i < n; i++)
        if (cps[i] < 0x80) { if (dyn_cp_put(out, cps[i])) return -1; b++; }
    h = b;
    if (b > 0)
        if (dyn_cp_put(out, PC_DELIM)) return -1;
    nval = PC_INITIAL_N; delta = 0; bias = PC_INITIAL_BIAS; nout = 0;
    while (h < n) {
        m = 0x110000;
        for (i = 0; i < n; i++)
            if (cps[i] >= nval && cps[i] < m)
                m = cps[i];
        delta += (int64_t)(m - nval) * (h + 1);
        /* A delta past INT32_MAX cannot belong to a representable label
           (punycode output grows ~2.5 octets per code point, and DNS caps
           labels at 63): refuse instead of emitting wrapped garbage. */
        if (delta > 0x7fffffff)
            return -1;
        nval = m;
        for (i = 0; i < n; i++) {
            if (cps[i] < nval)
                delta++;
            if (cps[i] == nval) {
                int q = delta, k;
                for (k = PC_BASE; ; k += PC_BASE) {
                    int t = (k <= bias) ? PC_TMIN
                            : (k >= bias + PC_TMAX ? PC_TMAX : k - bias);
                    int d;
                    if (q < t)
                        break;
                    d = t + (q - t) % (PC_BASE - t);
                    if (dyn_cp_put(out, d < 26 ? d + 'a' : d - 26 + '0')) return -1;
                    q = (q - t) / (PC_BASE - t);
                }
                if (dyn_cp_put(out, q < 26 ? q + 'a' : q - 26 + '0')) return -1;
                bias = pc_adapt(delta, h + 1, h == b);
                delta = 0;
                h++;
            }
        }
        delta++;
        nval++;
        nout++;
    }
    (void)nout;
    return 0;
}

/* Decode a punycode string (no "xn--" prefix) into `out`. Returns 0 or -1. */
static int pc_decode(const char *s, size_t n, dyn_cp_t *out)
{
    size_t ip = 0, i;
    uint32_t nval = PC_INITIAL_N;
    int bias = PC_INITIAL_BIAS;
    long long ival = 0;
    /* literal prefix before the last delimiter (only if non-empty) */
    ip = n;
    while (ip > 1 && s[ip - 1] != PC_DELIM)
        ip--;
    if (ip > 1) {
        /* the last delimiter is at ip-1 with a non-empty literal prefix
           (ip > 1); ip already points past it, so the digits start at ip.
           A delimiter at position 0 with an empty prefix is not consumed and
           stays in the encoded stream, where it fails as a non-digit. */
        size_t j;
        for (j = 0; j + 1 < ip; j++) {
            if ((unsigned char)s[j] >= 0x80)
                return -1;
            if (dyn_cp_put(out, (unsigned char)s[j])) return -1;
        }
    } else {
        ip = 0;
    }
    while (ip < n) {
        long long oldi = ival;
        long long w = 1;
        int k;
        for (k = PC_BASE; ; k += PC_BASE) {
            int d, t;
            if (ip >= n)
                return -1;
            d = pc_digit((unsigned char)s[ip++]);
            if (d < 0)
                return -1;
            if (d > (0x7FFFFFFF - ival) / w)
                return -1;
            ival += d * w;
            t = (k <= bias) ? PC_TMIN : (k >= bias + PC_TMAX ? PC_TMAX : k - bias);
            if (d < t)
                break;
            if (w > (0x7FFFFFFF - (PC_BASE - t)) / (PC_BASE - t))
                return -1;
            w *= PC_BASE - t;
        }
        {
            size_t outlen = out->n + 1;
            bias = pc_adapt((int)(ival - oldi), (int)outlen, oldi == 0);
            nval += (uint32_t)(ival / (long long)outlen);
            ival %= (long long)outlen;
        }
        if (nval > 0x10FFFF || (nval >= 0xD800 && nval <= 0xDFFF))
            return -1;
        {
            uint32_t *arr = (uint32_t *)realloc(out->p, (out->n + 1) * sizeof(uint32_t));
            if (!arr)
                return -1;
            out->p = arr;
            for (i = out->n; i > (size_t)ival; i--)
                out->p[i] = out->p[i - 1];
            out->p[ival] = nval;
            out->n++;
            out->cap = out->n;
        }
        ival++;
    }
    return 0;
}

/* ---------------- per-codepoint property helpers ---------------- */
/* Joining_Type: 0=L 1=D 2=R 3=T 4=U */
static int dyn_idna_jt(uint32_t cp)
{
    int i = dyn_tab3(idna_jt, countof(idna_jt), cp);
    if (i >= 0)
        return (int)idna_jt[i][2];
    if (dyn_tab2(idna_jt_transparent, countof(idna_jt_transparent), cp) >= 0)
        return 3;
    return 4;
}

static int dyn_idna_virama(uint32_t cp)
{
    return dyn_tab2(idna_virama, countof(idna_virama), cp) >= 0;
}

static int dyn_idna_combining(uint32_t cp)
{
    return dyn_tab2(idna_combining, countof(idna_combining), cp) >= 0;
}

/* Bidi_Class: 0=L 1=R 2=AL 3=AN 4=EN 5=NSM 6=neutral */
static int dyn_idna_bidi_class(uint32_t cp)
{
    int i = dyn_tab3(idna_bidi, countof(idna_bidi), cp);
    return i >= 0 ? (int)idna_bidi[i][2] : 6;
}

/* NFC exactly as the module calls it (libc realloc via dyn_dbuf_realloc) */
static int idna_nfc(const uint32_t *src, int n, uint32_t **pout)
{
    return unicode_normalize(pout, src, n, UNICODE_NFC, NULL, dyn_dbuf_realloc);
}

static int idna_is_nfc(const uint32_t *cps, int n)
{
    uint32_t *norm;
    int nl = idna_nfc(cps, n, &norm);
    if (nl < 0)
        return 1;
    if (nl != n) { free(norm); return 0; }
    if (memcmp(norm, cps, (size_t)n * sizeof(uint32_t)) != 0) { free(norm); return 0; }
    free(norm);
    return 1;
}

/* ---------------- labels ---------------- */
typedef struct { size_t off, len; int decoded; } lab_t;
typedef struct { lab_t *a; size_t n, cap; int oom; } labs_t;

static void labs_init(labs_t *l) { l->a = NULL; l->n = l->cap = 0; l->oom = 0; }
static void labs_free(labs_t *l) { free(l->a); l->a = NULL; l->n = l->cap = 0; }
static int labs_put(labs_t *l, size_t off, size_t len)
{
    if (l->n == l->cap) {
        size_t nc = l->cap ? l->cap * 2 : 16;
        lab_t *na = (lab_t *)realloc(l->a, nc * sizeof(lab_t));
        if (!na) { l->oom = 1; return -1; }
        l->a = na; l->cap = nc;
    }
    l->a[l->n].off = off; l->a[l->n].len = len; l->a[l->n].decoded = 0;
    l->n++;
    return 0;
}

/* ---------------- processing result ---------------- */
typedef struct {
    int trans;           /* transitional processing */
    dyn_cp_t cps;        /* processed codepoint array */
    labs_t labs;         /* labels into cps */
    int nerrors;
    const char *stage;   /* first error's stage */
    int oom;             /* allocation failure (not a UTS #46 error) */
} proc_t;

static void proc_err(proc_t *p, const char *stage)
{
    p->nerrors++;
    if (!p->stage)
        p->stage = stage;
}

/* validation of one label; `trans` is the effective transitional mode for it */
static void idna_validate(proc_t *p, size_t off, size_t len, int trans,
                          int bidi_domain, int check_joiners)
{
    const uint32_t *lab = p->cps.p + off;
    size_t i;
    if (len == 0)
        return;
    if (len >= 4 && lab[0] == 'x' && lab[1] == 'n' && lab[2] == '-' && lab[3] == '-')
        proc_err(p, "validation");                      /* V4 */
    if (len >= 4 && lab[2] == '-' && lab[3] == '-')
        proc_err(p, "validation");                      /* V2 */
    if (lab[0] == '-' || lab[len - 1] == '-')
        proc_err(p, "validation");                      /* V3 */
    if (dyn_idna_combining(lab[0]))
        proc_err(p, "validation");                      /* V6 */
    for (i = 0; i < len; i++) {
        int st = dyn_idna_status(lab[i]);
        int ok = (st == IDNA_ST_VALID) || (st == IDNA_ST_DEVIATION && !trans);
        if (!ok)
            proc_err(p, "validation");                  /* V7 */
        if (lab[i] < 0x80 &&
            !((lab[i] >= 'a' && lab[i] <= 'z') || (lab[i] >= '0' && lab[i] <= '9') ||
              lab[i] == '-'))
            proc_err(p, "validation");                  /* U1 */
    }
    for (i = 0; i < len && check_joiners; i++) {
        if (lab[i] == 0x200C) {
            int ok = 0;
            if (i > 0 && dyn_idna_virama(lab[i - 1]))
                continue;
            {
                long long j = (long long)i - 1;
                while (j >= 0 && dyn_idna_jt(lab[j]) == 3) j--;
                if (j >= 0 && (dyn_idna_jt(lab[j]) == 0 || dyn_idna_jt(lab[j]) == 1)) {
                    size_t k = i + 1;
                    while (k < len && dyn_idna_jt(lab[k]) == 3) k++;
                    if (k < len && (dyn_idna_jt(lab[k]) == 1 || dyn_idna_jt(lab[k]) == 2))
                        ok = 1;
                }
            }
            if (!ok)
                proc_err(p, "validation");              /* C1 */
        } else if (lab[i] == 0x200D) {
            if (!(i > 0 && dyn_idna_virama(lab[i - 1])))
                proc_err(p, "validation");              /* C2 */
        }
    }
    if (bidi_domain) {
        int c0 = dyn_idna_bidi_class(lab[0]);
        if (!(c0 == 0 || c0 == 1 || c0 == 2)) { proc_err(p, "validation"); return; }  /* B1 */
        if (c0 == 1 || c0 == 2) {
            for (i = 0; i < len; i++)
                if (dyn_idna_bidi_class(lab[i]) == 0) { proc_err(p, "validation"); break; }  /* B2 */
            {
                long long k = (long long)len - 1;
                while (k >= 0 && dyn_idna_bidi_class(lab[k]) == 5) k--;
                if (k < 0 || (dyn_idna_bidi_class(lab[k]) != 1 && dyn_idna_bidi_class(lab[k]) != 2 &&
                              dyn_idna_bidi_class(lab[k]) != 4 && dyn_idna_bidi_class(lab[k]) != 3))
                    proc_err(p, "validation");          /* B3 */
            }
            {
                int has_en = 0, has_an = 0;
                for (i = 0; i < len; i++) {
                    if (dyn_idna_bidi_class(lab[i]) == 4) has_en = 1;
                    if (dyn_idna_bidi_class(lab[i]) == 3) has_an = 1;
                }
                if (has_en && has_an) proc_err(p, "validation");  /* B4 */
            }
        } else {
            for (i = 0; i < len; i++)
                if (dyn_idna_bidi_class(lab[i]) == 1 || dyn_idna_bidi_class(lab[i]) == 2 ||
                    dyn_idna_bidi_class(lab[i]) == 3) { proc_err(p, "validation"); break; }  /* B5 */
            {
                long long k = (long long)len - 1;
                while (k >= 0 && dyn_idna_bidi_class(lab[k]) == 5) k--;
                if (k < 0 || (dyn_idna_bidi_class(lab[k]) != 0 && dyn_idna_bidi_class(lab[k]) != 4))
                    proc_err(p, "validation");          /* B6 */
            }
        }
    }
}

/* The UTS #46 processing steps. Returns processed labels + errors. */
/* mode: 0 = ToUnicode, 1 = ToASCII nontransitional, 2 = ToASCII
   transitional. UTS #46: ToASCII-N applies NO validity criteria (map, NFC,
   punycode, VerifyDnsLength only); ToASCII-T is ToUnicode on the
   transitionally-mapped form, then punycode -- so its status carries the
   B/V validity codes while N's does not (the conformance file pins both). */
static proc_t idna_process(const uint32_t *src, int n, int transitional,
                          int mode)
{
    proc_t p;
    dyn_cp_t mapped, rebuilt;
    uint32_t *norm = NULL;
    int norm_len, i;
    size_t k;
    int bidi_domain = 0;

    memset(&p, 0, sizeof(p));
    p.trans = transitional;
    dyn_cp_init(&p.cps);
    labs_init(&p.labs);
    dyn_cp_init(&mapped);
    dyn_cp_init(&rebuilt);

    /* step 1: map */
    for (i = 0; i < n; i++) {
        if (dyn_idna_map_cp(src[i], transitional, mode != 0, &mapped))
            goto oom;
    }
    /* step 2: NFC */
    norm_len = idna_nfc(mapped.p, (int)mapped.n, &norm);
    if (norm_len < 0) { proc_err(&p, "validation"); goto done; }
    /* step 3: split into labels on U+002E */
    {
        size_t start = 0;
        int j;
        for (j = 0; j <= norm_len; j++) {
            if (j == norm_len || norm[j] == 0x2E) {
                if (labs_put(&p.labs, start, (size_t)j - start)) goto oom2;
                start = (size_t)j + 1;
            }
        }
        /* 63/253 BEFORE punycode expansion (toASCII only -- toUnicode
           deliberately has no DNS-length check, pinned by test_idna.js):
           punycode only grows labels, so a mapped label over 63 code points
           can never encode under 64 octets, and the same holds for the
           whole domain at 253. Refusing nothing valid bounds the work of
           steps 4-5. All modes get the 4096-cp work cap: no real domain is
           that long, and pc_decode inserts make huge labels a DoS. */
        {
            size_t total = 0, ndots = 0;
            int j2;
            if (norm_len > 4096)
                proc_err(&p, "validation");
            for (j2 = 0; j2 < p.labs.n; j2++) {
                if (mode != 0 && p.labs.a[j2].len > 63)
                    proc_err(&p, "dns-length");
                total += p.labs.a[j2].len;
                if (j2 + 1 < p.labs.n)
                    ndots++;
            }
            if (p.labs.n > 0 && p.labs.a[p.labs.n - 1].len == 0)
                ndots--;                    /* trailing dot is the root label */
            total += ndots;
            if (mode != 0 && total > 253)
                proc_err(&p, "dns-length");
        }
    }
    /* step 4: decode A-labels, rebuild the codepoint array */
    for (k = 0; k < p.labs.n; k++) {
        lab_t *l = &p.labs.a[k];
        const uint32_t *lab = norm + l->off;
        int is_alabel = l->len >= 4 && lab[0] == 'x' && lab[1] == 'n' &&
                        lab[2] == '-' && lab[3] == '-';
        if (!is_alabel) {
            for (i = 0; i < (int)l->len; i++)
                if (dyn_cp_put(&rebuilt, lab[i])) goto oom2;
            l->off = rebuilt.n - l->len;
            continue;
        }
        {
            int nonascii = 0;
            for (i = 4; i < (int)l->len; i++)
                if (lab[i] > 0x7F) { nonascii = 1; break; }
            if (nonascii) {
                proc_err(&p, "punycode");               /* P4 */
                for (i = 0; i < (int)l->len; i++)
                    if (dyn_cp_put(&rebuilt, lab[i])) goto oom2;
                l->off = rebuilt.n - l->len;
                continue;
            }
        }
        {
            dyn_cp_t dec;
            char *bs = (char *)malloc(l->len - 3);
            size_t j, blen;
            int all_ascii = 1;
            if (!bs) goto oom2;
            dyn_cp_init(&dec);
            for (j = 0; j + 4 < l->len; j++)
                bs[j] = (char)lab[j + 4];
            blen = l->len - 4;
            if (pc_decode(bs, blen, &dec) < 0) {
                proc_err(&p, "punycode");               /* P4: decode failure */
                l->len = 0;                             /* label dropped */
                l->off = rebuilt.n;
                free(bs);
                dyn_cp_free(&dec);
                continue;
            }
            free(bs);
            for (j = 0; j < dec.n; j++)
                if (dec.p[j] > 0x7F) { all_ascii = 0; break; }
            if (dec.n == 0 || all_ascii)
                proc_err(&p, "punycode");               /* P4: empty/ASCII-only */
            l->decoded = 1;
            l->off = rebuilt.n;
            for (j = 0; j < dec.n; j++)
                if (dyn_cp_put(&rebuilt, dec.p[j])) { dyn_cp_free(&dec); goto oom2; }
            l->len = dec.n;
            dyn_cp_free(&dec);
        }
    }
    /* copy rebuilt into p.cps with '.' separators between labels, and
       recompute each label offset (the rebuild appended labels without dots) */
    {
        size_t acc = 0, ri = 0;
        for (k = 0; k < p.labs.n; k++) {
            p.labs.a[k].off = acc;
            {
                size_t j;
                for (j = 0; j < p.labs.a[k].len; j++) {
                    if (dyn_cp_put(&p.cps, rebuilt.p[ri++])) goto oom2;
                }
            }
            acc += p.labs.a[k].len;
            if (k + 1 < p.labs.n) {
                if (dyn_cp_put(&p.cps, 0x2E)) goto oom2;
                acc++;
            }
        }
    }

    /* bidi domain: any label with R/AL/AN */
    for (k = 0; k < p.labs.n; k++) {
        lab_t *l = &p.labs.a[k];
        for (i = 0; i < (int)l->len; i++) {
            int bc = dyn_idna_bidi_class(p.cps.p[l->off + i]);
            if (bc == 1 || bc == 2 || bc == 3) { bidi_domain = 1; break; }
        }
        if (bidi_domain) break;
    }
    /* empty-label rule + validation: EVERY mode -- ToASCII's status is the
       ToUnicode status of its result (the conformance file's blank
       toAsciiN/toAsciiT statuses INHERIT the toUnicode status). */
    {
        size_t nempty = 0;
        for (k = 0; k < p.labs.n; k++)
            if (p.labs.a[k].len == 0) nempty++;
        if (nempty) {
            int trailing_only = nempty == 1 && p.labs.a[p.labs.n - 1].len == 0 &&
                                p.labs.n > 1;
            if (!trailing_only)
                proc_err(&p, "validation");             /* X4_2 */
        }
    }
    /* validate */
    for (k = 0; k < p.labs.n; k++) {
        lab_t *l = &p.labs.a[k];
        const uint32_t *lab = p.cps.p + l->off;
        int is_failed_alabel = !l->decoded && l->len >= 4 &&
                               lab[0] == 'x' && lab[1] == 'n' &&
                               lab[2] == '-' && lab[3] == '-';
        if (l->len == 0 || is_failed_alabel)
            continue;
        if (l->decoded) {
            /* decoded A-labels: NFC re-check + nontransitional validation */
            if (!idna_is_nfc(lab, (int)l->len))
                proc_err(&p, "validation");             /* V1 */
            idna_validate(&p, l->off, l->len, 0, bidi_domain, 1);
        } else {
            idna_validate(&p, l->off, l->len, transitional, bidi_domain, 1);
        }
    }
done:
    dyn_cp_free(&mapped);
    dyn_cp_free(&rebuilt);
    free(norm);
    return p;
oom2:
    dyn_cp_free(&rebuilt);
oom:
    p.oom = 1;
    proc_err(&p, "validation");
    free(norm);
    dyn_cp_free(&mapped);
    return p;
}

/* toASCII: processing + punycode-encode + DNS length. Returns labels. */
static void idna_to_ascii(proc_t *p, const uint32_t *src, int n, int transitional,
                          dyn_cp_t *out_ascii)
{
    proc_t proc = idna_process(src, n, transitional, transitional ? 2 : 1);
    size_t k;
    *p = proc;
    for (k = 0; k < proc.labs.n; k++) {
        lab_t *l = &proc.labs.a[k];
        int has_nonascii = 0, i;
        size_t start = out_ascii->n;
        for (i = 0; i < (int)l->len; i++)
            if (proc.cps.p[l->off + i] > 0x7F) { has_nonascii = 1; break; }
        if (!has_nonascii) {
            for (i = 0; i < (int)l->len; i++)
                if (dyn_cp_put(out_ascii, proc.cps.p[l->off + i])) goto oom;
            if (k + 1 < proc.labs.n)
                if (dyn_cp_put(out_ascii, 0x2E)) goto oom;
            (void)start;
            continue;
        }
        /* xn-- prefix */
        if (dyn_cp_put(out_ascii, 'x')) goto oom;
        if (dyn_cp_put(out_ascii, 'n')) goto oom;
        if (dyn_cp_put(out_ascii, '-')) goto oom;
        if (dyn_cp_put(out_ascii, '-')) goto oom;
        {
            dyn_cp_t lab;
            dyn_cp_init(&lab);
            for (i = 0; i < (int)l->len; i++) {
                uint32_t cp = proc.cps.p[l->off + i];
                if (dyn_idna_status(cp) == IDNA_ST_DISALLOWED)
                    continue;
                if (dyn_cp_put(&lab, cp)) { dyn_cp_free(&lab); goto oom; }
            }
            if (pc_encode(lab.p, (int)lab.n, out_ascii) < 0)
                proc_err(p, "punycode");                /* A3 */
            dyn_cp_free(&lab);
        }
        if (k + 1 < proc.labs.n)
            if (dyn_cp_put(out_ascii, 0x2E)) goto oom;
    }
    /* VerifyDnsLength on the encoded wire form. The limit is the length of
       the domain name excluding the root label and its dot: every label's
       octets plus one separator between consecutive non-root labels. */
    {
        size_t total = 0, lablen = 0, ndots = 0, nlabels = 0;
        size_t i;
        for (i = 0; i <= out_ascii->n; i++) {
            if (i == out_ascii->n || out_ascii->p[i] == 0x2E) {
                if (lablen == 0)
                    proc_err(p, "dns-length");          /* A4_2: empty label */
                else if (lablen > 63)
                    proc_err(p, "dns-length");          /* A4_1: label > 63 */
                total += lablen;
                nlabels++;
                if (i < out_ascii->n)
                    ndots++;
                lablen = 0;
            } else {
                lablen++;
            }
        }
        /* a trailing dot is the root label's own dot and is not counted */
        if (out_ascii->n > 0 && out_ascii->p[out_ascii->n - 1] == 0x2E)
            ndots--;
        total += ndots;
        if (total == 0)
            proc_err(p, "dns-length");                  /* A4: empty domain */
        if (total > 253)
            proc_err(p, "dns-length");                  /* A4_2: domain > 253 */
        (void)nlabels;
    }
    return;
oom:
    p->oom = 1;
    proc_err(p, "validation");
}

/* ----------------------------------------------------------- IDNA exports */

/* JS string -> codepoint array. The engine keeps lone surrogates in strings
   and JS_ToCStringLen encodes them; unicode_from_utf8 restores them, so the
   codec can reject them where RFC 3492 demands. */
static int dyn_idna_js_to_cps(JSContext *ctx, JSValueConst v, dyn_cp_t *out)
{
    size_t n;
    const char *s = JS_ToCStringLen(ctx, &n, v);
    const uint8_t *p, *end;
    if (!s)
        return -1;
    p = (const uint8_t *)s;
    end = p + n;
    while (p < end) {
        const uint8_t *np;
        int c = unicode_from_utf8(p, (int)(end - p), &np);
        if (c < 0 || dyn_cp_put(out, (uint32_t)c)) {
            JS_FreeCString(ctx, s);
            return -1;
        }
        p = np;
    }
    JS_FreeCString(ctx, s);
    return 0;
}

/* codepoints -> JS string (UTF-8) */
static JSValue dyn_idna_cps_to_js(JSContext *ctx, const uint32_t *cps, size_t n)
{
    /* a real BYTE buffer: cps is uint32_t, JS_NewStringLen wants bytes */
    char *buf;
    size_t cap, blen = 0, i;
    JSValue r;

    cap = n * UTF8_CHAR_LEN_MAX + 1;
    buf = (char *)malloc(cap);
    if (!buf)
        return JS_ThrowOutOfMemory(ctx);
    for (i = 0; i < n; i++) {
        int len = unicode_to_utf8((uint8_t *)buf + blen, cps[i]);
        if (len <= 0) {
            free(buf);
            return JS_ThrowTypeError(ctx,
                "dyna:url: cannot encode code point U+%04X as UTF-8", cps[i]);
        }
        blen += (size_t)len;
    }
    r = JS_NewStringLen(ctx, buf, blen);
    free(buf);
    return r;
}

/* optional { transitional: bool } on the domain functions; 0/1, -1 = throw */
static int dyn_idna_opts_transitional(JSContext *ctx, int argc, JSValueConst *argv)
{
    JSValue v;
    int b;
    if (argc < 2 || !JS_IsObject(argv[1]))
        return 0;
    v = JS_GetPropertyStr(ctx, argv[1], "transitional");
    if (JS_IsException(v))
        return -1;
    b = JS_ToBool(ctx, v);
    JS_FreeValue(ctx, v);
    return b;
}

/* BOSCC bypass: pure-ASCII domains without xn-- labels or invalid characters
   can be validated and lowercased in a single pass without Unicode mapping,
   NFC normalization, or dynamic codepoint array allocations. */
static int idna_ascii_fast_check(const char *s, size_t len)
{
    size_t i, lablen = 0, total = 0, ndots = 0;
    if (len == 0 || len > 254)
        return 0;
    for (i = 0; i <= len; i++) {
        char c = (i < len) ? s[i] : '.';
        if (c == '.') {
            if (i == len && i > 0 && s[i - 1] == '.')
                break;                  /* trailing root dot */
            if (lablen == 0 || lablen > 63)
                return 0;
            if (s[i - lablen] == '-' || s[i - 1] == '-')
                return 0;
            if (lablen >= 4 && s[i - lablen + 2] == '-' && s[i - lablen + 3] == '-')
                return 0;               /* xn-- or internal hyphen */
            total += lablen;
            ndots++;
            lablen = 0;
        } else {
            unsigned char uc = (unsigned char)c;
            if (uc >= 0x80)
                return 0;
            if (!((uc >= 'a' && uc <= 'z') || (uc >= 'A' && uc <= 'Z') ||
                  (uc >= '0' && uc <= '9') || uc == '-'))
                return 0;
            lablen++;
        }
    }
    if (len > 0 && s[len - 1] == '.')
        ndots--;
    total += ndots;
    if (total == 0 || total > 253)
        return 0;
    return 1;
}

static JSValue dyn_domain_to_ascii(JSContext *ctx, JSValueConst this_val,
                                   int argc, JSValueConst *argv)
{
    dyn_cp_t src, out;
    proc_t p;
    int trans;
    JSValue r;
    size_t slen = 0;
    const char *cstr;
    (void)this_val;
    if (argc < 1 || !JS_IsString(argv[0]))
        return JS_ThrowTypeError(ctx,
            "domainToASCII(domain[, opts]): argument must be a string");
    trans = dyn_idna_opts_transitional(ctx, argc, argv);
    if (trans < 0)
        return JS_EXCEPTION;

    cstr = JS_ToCStringLen(ctx, &slen, argv[0]);
    if (cstr) {
        if (idna_ascii_fast_check(cstr, slen)) {
            char *buf = (char *)malloc(slen + 1);
            if (buf) {
                size_t k;
                for (k = 0; k < slen; k++) {
                    char c = cstr[k];
                    if (c >= 'A' && c <= 'Z')
                        c = (char)(c + 32);
                    buf[k] = c;
                }
                buf[slen] = 0;
                JS_FreeCString(ctx, cstr);
                r = JS_NewStringLen(ctx, buf, slen);
                free(buf);
                return r;
            }
        }
        JS_FreeCString(ctx, cstr);
    }

    dyn_cp_init(&src);
    dyn_cp_init(&out);
    if (dyn_idna_js_to_cps(ctx, argv[0], &src) < 0) {
        dyn_cp_free(&src);
        return JS_ThrowOutOfMemory(ctx);
    }
    idna_to_ascii(&p, src.p, (int)src.n, trans, &out);
    dyn_cp_free(&src);
    if (p.oom) {
        labs_free(&p.labs);
        dyn_cp_free(&p.cps);
        dyn_cp_free(&out);
        return JS_ThrowOutOfMemory(ctx);
    }
    if (p.nerrors) {
        const char *stage = p.stage ? p.stage : "validation";
        labs_free(&p.labs);
        dyn_cp_free(&p.cps);
        dyn_cp_free(&out);
        return JS_ThrowTypeError(ctx, "domainToASCII: %s error", stage);
    }
    r = dyn_idna_cps_to_js(ctx, out.p, out.n);
    labs_free(&p.labs);
    dyn_cp_free(&p.cps);
    dyn_cp_free(&out);
    return r;
}

static JSValue dyn_domain_to_unicode(JSContext *ctx, JSValueConst this_val,
                                     int argc, JSValueConst *argv)
{
    dyn_cp_t src;
    proc_t p;
    int trans;
    JSValue r;
    (void)this_val;
    if (argc < 1 || !JS_IsString(argv[0]))
        return JS_ThrowTypeError(ctx,
            "domainToUnicode(domain[, opts]): argument must be a string");
    trans = dyn_idna_opts_transitional(ctx, argc, argv);
    if (trans < 0)
        return JS_EXCEPTION;
    dyn_cp_init(&src);
    if (dyn_idna_js_to_cps(ctx, argv[0], &src) < 0) {
        dyn_cp_free(&src);
        return JS_ThrowOutOfMemory(ctx);
    }
    p = idna_process(src.p, (int)src.n, trans, 0);
    dyn_cp_free(&src);
    if (p.oom) {
        labs_free(&p.labs);
        dyn_cp_free(&p.cps);
        return JS_ThrowOutOfMemory(ctx);
    }
    if (p.nerrors) {
        const char *stage = p.stage ? p.stage : "validation";
        labs_free(&p.labs);
        dyn_cp_free(&p.cps);
        return JS_ThrowTypeError(ctx, "domainToUnicode: %s error", stage);
    }
    r = dyn_idna_cps_to_js(ctx, p.cps.p, p.cps.n);
    labs_free(&p.labs);
    dyn_cp_free(&p.cps);
    return r;
}

static JSValue dyn_punycode_encode(JSContext *ctx, JSValueConst this_val,
                                   int argc, JSValueConst *argv)
{
    dyn_cp_t src, out;
    JSValue r;
    (void)this_val;
    if (argc < 1 || !JS_IsString(argv[0]))
        return JS_ThrowTypeError(ctx, "punycodeEncode(text): argument must be a string");
    dyn_cp_init(&src);
    dyn_cp_init(&out);
    if (dyn_idna_js_to_cps(ctx, argv[0], &src) < 0) {
        dyn_cp_free(&src);
        return JS_ThrowOutOfMemory(ctx);
    }
    /* pc_encode is O(n^2) in the label length; a DNS label is <= 63 octets
       and a longer stream is a DoS, not data (mirrors the decode cap). */
    if (src.n > 1024) {
        dyn_cp_free(&src);
        return JS_ThrowRangeError(ctx, "punycodeEncode: input exceeds 1024 code points");
    }
    if (pc_encode(src.p, (int)src.n, &out) < 0) {
        dyn_cp_free(&src);
        dyn_cp_free(&out);
        return JS_ThrowTypeError(ctx,
            "punycodeEncode: cannot encode (lone surrogate or invalid code point)");
    }
    dyn_cp_free(&src);
    r = dyn_idna_cps_to_js(ctx, out.p, out.n);
    dyn_cp_free(&out);
    return r;
}

static JSValue dyn_punycode_decode(JSContext *ctx, JSValueConst this_val,
                                   int argc, JSValueConst *argv)
{
    dyn_cp_t out;
    JSValue r;
    size_t n;
    const char *s;
    (void)this_val;
    if (argc < 1 || !JS_IsString(argv[0]))
        return JS_ThrowTypeError(ctx, "punycodeDecode(text): argument must be a string");
    s = JS_ToCStringLen(ctx, &n, argv[0]);
    if (!s)
        return JS_EXCEPTION;
    /* the decoder inserts at arbitrary positions (O(n^2) on the output
       array): refuse unbounded input -- a DNS label is <= 63 octets, and a
       longer stream is a DoS, not data */
    if (n > 1024) {
        JS_FreeCString(ctx, s);
        return JS_ThrowRangeError(ctx, "punycodeDecode: input exceeds 1024 octets");
    }
    dyn_cp_init(&out);
    if (pc_decode(s, n, &out) < 0) {
        JS_FreeCString(ctx, s);
        dyn_cp_free(&out);
        return JS_ThrowTypeError(ctx, "punycodeDecode: invalid punycode input");
    }
    JS_FreeCString(ctx, s);
    r = dyn_idna_cps_to_js(ctx, out.p, out.n);
    dyn_cp_free(&out);
    return r;
}
